/**
 * The single error type of the Swift API. UniFFI errors must be enums, so the
 * structured CoreError travels as the one `Core` variant.
 */
public 
enum FfiError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case Core(code: String, message: String, retryable: Bool
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

